export function getEmployeesByCompany(companyId: string): Employee[] {
  return employees.filter((e) => e.company_id === companyId);
}

export function getEmployeeById(id: string): Employee | undefined {
  return employees.find((e) => e.id === id);
}

export function getEmployeesByDepartment(companyId: string, department: string): Employee[] {
  return employees.filter(
    (e) => e.company_id === companyId && e.department === department
  );
}

export function getDepartmentHeads(companyId: string): Employee[] {
  return employees.filter(
    (e) => e.company_id === companyId && e.is_department_head
  );
}

export function getHighPotentialEmployees(companyId?: string): Employee[] {
  return employees.filter(
    (e) => e.potential === "high" && (!companyId || e.company_id === companyId)
  );
}

export function getRelocationReadyEmployees(): Employee[] {
  return employees.filter((e) => e.relocation_ready);
}
